const base = 'https://github.com/Azure/';
const details = {
 provision:['AZURE INFRASTRUCTURE','The CLI asks Azure to create the environment.','Bicep describes the Azure resources: AKS Automatic, managed identities, and the required data services. The CLI orchestrates their provisioning. This creates the foundation that will host OSDU; it does not yet prove the APIs are ready.'],
 bootstrap:['CLUSTER PREPARATION','The cluster needs configuration before it can host the services.','The CLI supplies runtime configuration, identity bindings, and other bootstrap inputs, then activates Flux. These connect the newly created Azure environment to the Kubernetes workloads that will use it.'],
 reconcile:['WORKLOAD ASSEMBLY','Flux brings the workloads toward their declared state.','Flux is the controller that applies the workload configuration. Dependency ordering brings up operators and middleware before core OSDU services and initialization jobs. Reconciliation continues after the CLI hands off; inspect readiness and an API response to establish usability.'],
 client:['FAMILIAR TERRITORY','The OSDU contract stays familiar.','Clients still call OSDU APIs. Azure-specific persistence and messaging sit behind the service boundary; the client does not select Cosmos DB or Service Bus directly.'],
 gateway:['REQUEST ENTRY','The gateway gets the request to the service.','The Istio gateway routes traffic. At the receiving service, the sidecar validates the bearer and projects the identity headers expected by the Azure provider. Application authorization is still a separate check.'],
 service:['APPLICATION','The OSDU application runs here.','OSDU services run as workloads on Azure Kubernetes Service (AKS). Their common code and Azure provider are packaged together. The stack supplies the runtime, configuration, and dependencies they need; the next views explain how those pieces come together.'],
 provider:['THE AZURE SPI','The provider implements the cloud-specific work.','Shared service code depends on provider interfaces. The Azure implementation supplies the storage, messaging, and other cloud-specific operations those interfaces require. Its backend choices vary by service.'],
 middleware:['IN THE CLUSTER','Some dependencies run alongside OSDU.','SPI Stack places middleware such as Elasticsearch and Redis in the platform namespace. These are separate from both the OSDU service workloads and Azure-managed data services.'],
 data:['AZURE MANAGED SERVICES','Azure holds the service’s operational data.','The stack provisions Azure backends such as Cosmos DB, Storage, and Service Bus. Service code reaches them through the Azure provider, using Workload Identity for Azure access. The diagram groups examples; it is not one service’s complete dependency list.'],
 contract:['THE CODE BOUNDARY','An interface separates the operation from its implementation.','The common service expresses what it needs through the SPI contract. An Azure provider implements that contract. A changed interface can require an Azure adaptation even when the public OSDU API has not changed.'],
 core:['SHARED CODE','OSDU behavior stays connected to upstream.','The fork consumes shared service code and interfaces from upstream OSDU. Keeping that relationship intact is why the engineering system controls how upstream changes enter the service repository.'],
 azureimpl:['FORK-OWNED CODE','The fork owns its Azure implementation.','The engineering system seeds Azure provider and test source, then preserves that ownership while synchronizing shared upstream content. Azure work is developed and reviewed in the service repository.'],
 upstream:['UPSTREAM OSDU','Community changes arrive through controlled integration.','Shared code enters the service fork through filtered upstream synchronization and an integration branch. Provider implementations are excluded from the generated upstream tree. The branch mechanics come later in the guide.'],
 template:['ENGINEERING SYSTEM · osdu-spi','Shared automation follows the service repositories.','The engineering system supplies build, synchronization, validation, and release workflows. Updating that machinery belongs in osdu-spi; updating an Azure provider belongs in its service repository.'],
 repo:['SERVICE REPOSITORY','This is where the Azure service evolves.','The repository combines synchronized shared code with fork-owned Azure code and tests. Its validation builds a service image. On eligible, onboarded runs, the deploy lane can prove that image against a running stack.'],
 stack:['RUNTIME ENVIRONMENT · osdu-spi-stack','The stack provides somewhere to run and prove the service.','The CLI and Bicep provision Azure infrastructure and bootstrap the cluster. Flux reconciles the Kubernetes workloads. The stack also reports environment facts and exposes the image-pin mechanism used for service testing.'],
 image:['THE HANDOFF','An image connects service engineering to the running stack.','A service build produces an image. A test deployment pins a specific digest in the stack’s image lock, lets Flux reconcile it, and verifies the running image. Building the image and deploying it are separate steps.'],
 proof:['TEMPORARY DEPLOYMENT','Borrow, prove, restore.','The engineering workflow can temporarily pin a candidate image, run the declared suites, and attempt ownership-checked restoration. The stack owns the deployment mechanism; the engineering system orchestrates the test run.']
};
Object.assign(details, architectureDetails);
function node(id,title,sub='',kind='',label=''){return `<button class="node ${kind}" type="button" data-detail="${id}" aria-pressed="false">${label?`<span class="node-label">${label}</span>`:''}<b>${title}</b>${sub?`<small>${sub}</small>`:''}</button>`;}
const scenes = {
 'running-stack':{
  category:'WHAT IS A STACK?',headline:'One environment.<span>Clear boundaries.</span>',intro:'A stack is the complete environment that makes OSDU usable: a Kubernetes cluster, the services running inside it, and Azure resources around it. Your workstation controls that environment from outside.',figure:'Where the stack begins and ends',selected:'environment',takeaway:'<strong>AKS is one part of the stack.</strong> The stack boundary also includes the Azure data and support resources. The Azure SPI provider is code inside an OSDU service.',
  diagram:architectureOverview,
  sources:[['Stack architecture','osdu-spi-stack/blob/main/docs/architecture.md'],['Request authentication and Workload Identity','osdu-spi-stack/blob/main/docs/design/workload-identity.md']]
 },
 'bring-up':{
  category:'HOW IT COMES TO LIFE',headline:'From your terminal<span>to a running stack.</span>',intro:'Keep the same map in view as the environment takes shape. Move through five moments to see what you do, what the CLI creates, and what Flux assembles inside AKS.',figure:'Watch the environment take shape',selected:'localsetup',takeaway:'<strong>One creation command, several kinds of work.</strong> The CLI provisions Azure and prepares AKS; Flux reconciles workloads. Readiness and an authenticated API request establish usability.',
  diagram:creationWalkthrough,
  sources:[['Installation and prerequisites','osdu-spi-stack/blob/main/docs/install.md'],['Quick start','osdu-spi-stack/blob/main/README.md#quick-start'],['Deployment lifecycle','osdu-spi-stack/blob/main/docs/design/deployment-lifecycle.md'],['Workload ordering and reconciliation','osdu-spi-stack/blob/main/docs/design/flux-reconciliation.md']]
 },
 'spi-boundary':{
  category:'THE SPI BOUNDARY',headline:'Shared behavior.<span>Azure-specific work.</span>',intro:'SPI means Service Provider Interface. It separates an operation the common service needs from the cloud-specific code that performs it. Both live inside the service.',figure:'The boundary is in code',selected:'contract',takeaway:'<strong>The important distinction is ownership.</strong> A public API change, a shared-interface change, and an Azure implementation change are different engineering tasks.',
  diagram:()=>`<div class="boundary-labels"><span>SHARED OSDU CODE</span><span>AZURE-OWNED IMPLEMENTATION</span></div><div class="boundary-flow"><div class="scope"><div class="scope-label">COMMON SERVICE</div><div class="boundary-inner">${node('client','OSDU API','The client-facing contract')}${node('core','Shared service logic','Common behavior and provider interfaces','primary')}</div></div><div class="boundary-divider" aria-hidden="true">→</div><div class="scope provider-scope"><div class="scope-label">AZURE PROVIDER</div><div class="boundary-inner">${node('azureimpl','Azure implementation','Implements the provider contract','azure')}${node('data','Azure service clients','Reach the required backends')}</div></div></div><div class="contract-node">${node('contract','The SPI contract','Shared logic calls the interface; the Azure provider implements it.','','THE AGREEMENT BETWEEN THE TWO')}</div><div class="legend"><span>Synchronized shared code</span><span>Fork-owned Azure code</span></div>`,
  sources:[['SPI concepts and source ownership','osdu-spi/blob/main/doc/src/concepts.md'],['Engineering-system architecture','osdu-spi/blob/main/doc/src/architecture/overview.md']]
 },
 'engineering-system':{
  category:'HOW CHANGES ARRIVE',headline:'Three repositories.<span>Distinct responsibilities.</span>',intro:'The stack hosts the service. A service fork owns the Azure implementation. The engineering system supplies the machinery that keeps that fork buildable, testable, and aligned with upstream.',figure:'From source ownership to a running image',selected:'repo',takeaway:'<strong>Follow the change to its owner.</strong> Provider code: service fork. Shared automation: osdu-spi. Runtime infrastructure and configuration: osdu-spi-stack.',
  diagram:()=>`<div class="ownership"><div><div class="column-label">SHARED SOURCE</div>${node('upstream','OSDU upstream','Common code and interfaces')}<div class="flow-arrow">↓ &nbsp; filtered synchronization</div>${node('repo','Service fork','Shared code + Azure implementation','primary')}</div><div><div class="column-label">ENGINEERING MACHINERY</div>${node('template','osdu-spi','Workflows and build assets')}<div class="flow-arrow">↓ &nbsp; supplied to the service fork</div>${node('image','Service image','Built and identified by digest','azure')}</div><div><div class="column-label">ENVIRONMENT</div>${node('stack','osdu-spi-stack','Infrastructure and workload configuration')}<div class="flow-arrow">↓ &nbsp; provisions and reconciles</div>${node('stack','Running Azure stack','Hosts the service and its dependencies','primary')}</div></div><div class="engineering-foot">${node('image','Source becomes an image','Service fork → build → image → stack')}${node('proof','A candidate can be proven here','Pin → verify → test → restore')}</div>`,
  sources:[['Fork deployment and testing','osdu-spi-stack/blob/main/docs/design/fork-deployment.md'],['Borrow, prove, restore','osdu-spi/blob/main/doc/src/adr/041-borrow-prove-restore-lane.md'],['Upstream integration and branches','osdu-spi/blob/main/doc/src/architecture/three_branch_strategy.md']]
 }
};
const order=Object.keys(scenes);
function selectDetail(id){const [label,title,copy]=details[id];document.getElementById('detail-label').textContent=label;document.getElementById('detail-title').textContent=title;document.getElementById('detail-copy').textContent=copy;document.querySelectorAll('[data-detail]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.detail===id)));}
function render(){const key=location.hash.slice(1);const index=order.indexOf(key);const active=index<0?order[0]:key;const n=order.indexOf(active);const scene=scenes[active];document.querySelector('.exploration').dataset.scene=active;document.querySelectorAll('[data-chapter]').forEach(link=>{if(link.dataset.chapter===active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});document.getElementById('chapter-number').textContent=`0${n+1}`;document.getElementById('chapter-category').textContent=scene.category;document.getElementById('headline').innerHTML=scene.headline;document.getElementById('introduction').textContent=scene.intro;document.getElementById('figure-index').textContent=`FIG. 0${n+1}`;document.getElementById('figure-title').textContent=scene.figure;document.getElementById('diagram').innerHTML=scene.diagram();document.getElementById('takeaway').innerHTML=scene.takeaway;document.getElementById('sources').innerHTML=scene.sources.map(([label,path])=>`<a href="${base}${path}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')+'<small>Source references open separately. This guide illustrates behavior; it is not connected to a live stack.</small>';document.getElementById('source-details').open=false;document.getElementById('chapter-position').textContent=`${n+1} of ${order.length} · Inside the Azure stack`;const next=document.getElementById('next-link');next.href=`#${order[(n+1)%order.length]}`;next.innerHTML=[`Next: How it comes to life <span aria-hidden="true">→</span>`,`Next: The SPI boundary <span aria-hidden="true">→</span>`,`Next: How changes arrive <span aria-hidden="true">→</span>`,`Return to the stack <span aria-hidden="true">↗</span>`][n];selectDetail(scene.selected);if(active==='bring-up')setCreationMoment(creationMoment);document.title=`${document.querySelector('[aria-current="page"]>span:last-child').childNodes[0].textContent} · OSDU Fieldnotes`;}
document.getElementById('diagram').addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.detail)selectDetail(target.dataset.detail);else handleArchitectureClick(target);});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});render();
